// @vitest-environment jsdom
import { describe, expect, it, vi } from 'vitest';
import { AppUI } from './index';
import { COURSE_SUMMARIES, DEFAULT_COURSE_ID, RANDOM_COURSE_ID, getCourse } from '../courses';

const openSetup = (ui: AppUI, root: HTMLElement): HTMLSelectElement => {
  ui.navigate('play');
  return root.querySelector<HTMLSelectElement>('[name="course"]')!;
};

describe('course selector', () => {
  it('lists every registered course plus the random tour', () => {
    const root = document.createElement('div');
    const select = openSetup(new AppUI(root), root);
    const values = [...select.options].map(option => option.value);
    expect(values).toEqual([...COURSE_SUMMARIES.map(summary => summary.id), RANDOM_COURSE_ID]);
    for (const value of values) {
      if (value !== RANDOM_COURSE_ID) expect(getCourse(value), `course "${value}" must exist`).toBeDefined();
    }
    expect(select.value).toBe(DEFAULT_COURSE_ID);
  });

  it('preselects the launch course and starts a match with a real course id', () => {
    const root = document.createElement('div');
    const startMatch = vi.fn();
    const ui = new AppUI(root, { startMatch }, { initialCourseId: 'volcano' });
    const select = openSetup(ui, root);
    expect(select.value).toBe('volcano');
    root.querySelector<HTMLElement>('[data-start]')!.click();
    expect(startMatch).toHaveBeenCalledOnce();
    expect(startMatch.mock.calls[0]![1].courseId).toBe('volcano');
  });

  it('keeps the chosen course when navigating away and back', () => {
    const root = document.createElement('div');
    const ui = new AppUI(root);
    const select = openSetup(ui, root);
    select.value = 'space-station';
    select.dispatchEvent(new Event('change'));
    ui.navigate('main');
    expect(openSetup(ui, root).value).toBe('space-station');
  });
});
EOF
